    private void initTts(){tts=new TextToSpeech(this,result->{ttsReady=result==TextToSpeech.SUCCESS;if(ttsReady){int r=tts.setLanguage(new Locale("id","ID"));if(r==TextToSpeech.LANG_MISSING_DATA||r==TextToSpeech.LANG_NOT_SUPPORTED)tts.setLanguage(Locale.getDefault());tts.setSpeechRate(.96f);tts.setPitch(1f);tts.setOnUtteranceProgressListener(new UtteranceProgressListener(){public void onStart(String id){speaking=true;}public void onDone(String id){speaking=false;if(pendingListen&&voiceMode){pendingListen=false;postListen(600);}}public void onError(String id){speaking=false;if(pendingListen&&voiceMode){pendingListen=false;postListen(700);}}});}else setStatus("⚠ Suara LUNA gagal diinisialisasi. Coba aktifkan mesin Text-to-Speech Android.");});}

