        LinearLayout hello=card();hello.setOrientation(LinearLayout.HORIZONTAL);TextView av=text("◉",40,Color.WHITE,true);av.setGravity(Gravity.CENTER);av.setBackground(round(Color.rgb(24,70,150),100));hello.addView(av,new LinearLayout.LayoutParams(dp(78),dp(78)));LinearLayout ht=new LinearLayout(this);ht.setOrientation(LinearLayout.VERTICAL);ht.setPadding(dp(14),0,0,0);ht.addView(text("Halo, saya LUNA!",18,TEXT,true));ht.addView(text("Saya siap membantu Anda mengoperasikan\nAndroid dengan suara, teks, dan perintah langsung.",12,MUTED,false));hello.addView(ht,new LinearLayout.LayoutParams(0,-2,1));root.addView(hello);
        root.addView(section("STATUS LUNA"));status=text("Siap. Simpan Gemini API Key lalu coba bertanya.",12,TEXT,false);LinearLayout sc=card();sc.addView(status,new LinearLayout.LayoutParams(-1,dp(76)));root.addView(sc);
        root.addView(section("MODE OPERATOR"));LinearLayout mode=card();mode.setOrientation(LinearLayout.HORIZONTAL);TextView brain=text("◈",25,Color.WHITE,true);brain.setGravity(Gravity.CENTER);brain.setBackground(round(PURPLE,100));mode.addView(brain,new LinearLayout.LayoutParams(dp(52),dp(52)));LinearLayout mt=new LinearLayout(this);mt.setOrientation(LinearLayout.VERTICAL);mt.setPadding(dp(12),0,0,0);mt.addView(text("Model AI",11,MUTED,false));mt.addView(text("Gemini 2.5 Flash • Free Tier",14,TEXT,true));mt.addView(text("Teks • Screenshot • Operator",10,MUTED,false));mode.addView(mt,new LinearLayout.LayoutParams(0,-2,1));TextView rd=text("SIAP",11,GREEN,true);rd.setGravity(Gravity.CENTER);rd.setPadding(dp(11),dp(6),dp(11),dp(6));rd.setBackground(stroke(Color.TRANSPARENT,GREEN,20,dp(1)));mode.addView(rd);root.addView(mode);
        root.addView(section("PROSES KERJA"));LinearLayout process=card();process.setGravity(Gravity.CENTER);String[] ic={"◉","♬","◈","⚙","✓"};String[] lb={"Dengar","Pahami","Amati","Bertindak","Verifikasi"};for(int i=0;i<5;i++){LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);p.setGravity(Gravity.CENTER);TextView x=text(ic[i],20,i==4?Color.CYAN:PURPLE,true);x.setGravity(Gravity.CENTER);x.setBackground(round(Color.rgb(26,29,88),100));p.addView(x,new LinearLayout.LayoutParams(dp(42),dp(42)));TextView y=text(lb[i],9,MUTED,true);y.setGravity(Gravity.CENTER);p.addView(y,new LinearLayout.LayoutParams(dp(58),dp(28)));process.addView(p,new LinearLayout.LayoutParams(0,-2,1));if(i<4)process.addView(text("—",14,LINE,true),new LinearLayout.LayoutParams(dp(10),dp(45)));}root.addView(process);
        root.addView(section("PERINTAH CEPAT"));LinearLayout quick=card();quick.setOrientation(LinearLayout.VERTICAL);LinearLayout q1=row();q1.addView(quickButton("▦  Buka Facebook","buka Facebook"));q1.addView(quickButton("●  Buka WhatsApp","buka WhatsApp"));q1.addView(quickButton("☁  Cek cuaca","cek cuaca hari ini"));quick.addView(q1);LinearLayout q2=row();q2.addView(quickButton("▶  Buka YouTube","buka YouTube"));q2.addView(quickButton("🔊  Volume 50","volume 50"));q2.addView(quickButton("⚙  Pengaturan","buka pengaturan"));quick.addView(q2);root.addView(quick);
        LinearLayout voice=card();voice.setOrientation(LinearLayout.VERTICAL);LinearLayout vr=row();Button tb=actionButton("⌨  TEKS",Color.TRANSPARENT,TEXT);vr.addView(tb,new LinearLayout.LayoutParams(dp(90),dp(48)));TextView wave=text(")))    ◉    (((",19,PURPLE,true);wave.setGravity(Gravity.CENTER);vr.addView(wave,new LinearLayout.LayoutParams(0,dp(48),1));mic=actionButton("MIC",Color.TRANSPARENT,TEXT);vr.addView(mic,new LinearLayout.LayoutParams(dp(105),dp(48)));voice.addView(vr);TextView vt=text("Ketuk MIC → bicara → LUNA menjawab dengan suara",11,TEXT,true);vt.setGravity(Gravity.CENTER);vt.setPadding(0,dp(5),0,0);voice.addView(vt);root.addView(voice);
        LinearLayout cr=new LinearLayout(this);cr.setGravity(Gravity.CENTER_VERTICAL);command=new EditText(this);command.setHint("Ketik pertanyaan atau perintah…");command.setHintTextColor(Color.rgb(105,128,159));command.setTextColor(TEXT);command.setTextSize(14);command.setSingleLine(true);command.setPadding(dp(16),0,dp(10),0);command.setBackground(round(CARD2,28));cr.addView(command,new LinearLayout.LayoutParams(0,dp(54),1));send=actionButton("➤",PURPLE,Color.WHITE);LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(dp(58),dp(54));sp.setMargins(dp(8),0,0,0);cr.addView(send,sp);root.addView(cr);
        LinearLayout mr=new LinearLayout(this);mr.setPadding(0,dp(12),0,0);mr.setGravity(Gravity.CENTER);Button run=actionButton("▶  JALANKAN",PURPLE,Color.WHITE);mr.addView(run,new LinearLayout.LayoutParams(0,dp(54),1));stop=actionButton("■  STOP",RED,Color.WHITE);LinearLayout.LayoutParams stp=new LinearLayout.LayoutParams(0,dp(54),.45f);stp.setMargins(dp(7),0,0,0);mr.addView(stop,stp);root.addView(mr);
        LinearLayout tools=new LinearLayout(this);tools.setPadding(0,dp(10),0,0);access=outlineButton("♿  ACCESSIBILITY");key=outlineButton("⚿  GEMINI API KEY");tools.addView(access,new LinearLayout.LayoutParams(0,dp(50),1));LinearLayout kk=new LinearLayout(this);kk.setPadding(dp(8),0,0,0);kk.addView(key,new LinearLayout.LayoutParams(-1,dp(50)));tools.addView(kk,new LinearLayout.LayoutParams(0,dp(50),1));root.addView(tools);state=text("",10,MUTED,false);root.addView(state);TextView foot=text("LUNA  •  Observe → Reason → Act → Verify\nTekan STOP kapan saja untuk menghentikan operator.",10,MUTED,false);foot.setPadding(dp(4),dp(12),dp(4),0);root.addView(foot);setContentView(outer);
        send.setOnClickListener(v->runCommand(command.getText().toString()));run.setOnClickListener(v->runCommand(command.getText().toString()));stop.setOnClickListener(v->stopAll());access.setOnClickListener(v->startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS)));key.setOnClickListener(v->showKeyDialog());mic.setOnClickListener(v->toggleVoice());tb.setOnClickListener(v->{command.requestFocus();command.setSelection(command.length());});refreshState();
